const prizes=[{id:'millennium-falcon',name:'Millennium Falcon™',theme:'Star Wars™',set:'75192',pieces:'7,541',price:200,sold:125,max:200,tag:'THE BIG BUILD',image:'https://www.lego.com/cdn/cs/set/assets/blt3349f56c6f192e18/75192_Prod.png',description:'An iconic starship. An extraordinary build. Explore the intricate details of this Ultimate Collector Series Millennium Falcon, from its cockpit to its incredible interior.'},{id:'ferrari-daytona',name:'Ferrari Daytona SP3',theme:'Technic™',set:'42143',pieces:'3,778',price:200,sold:103,max:200,tag:'FOR THE DREAM GARAGE',image:'https://www.lego.com/cdn/cs/set/assets/bltb862bc546852bd71/42143.png',description:'Bring the spirit of Italian engineering to your collection with this detailed Ferrari Daytona SP3 building set.'},{id:'rivendell',name:'Rivendell™',theme:'The Lord of the Rings™',set:'10316',pieces:'6,167',price:200,sold:48,max:200,tag:'ESCAPE TO MIDDLE-EARTH',image:'https://www.lego.com/cdn/cs/set/assets/bltec012c948c003fba/10316_alt16.png',description:'Lose yourself in a richly detailed building experience inspired by the peaceful valley of Rivendell.'}];
const questionPools={
'millennium-falcon':[
{id:'falcon-type',text:'What type of vehicle is the Millennium Falcon?',options:['Spaceship','Submarine','Motorbike'],correct:'Spaceship'},
{id:'falcon-series',text:'Which film series features the Millennium Falcon?',options:['Star Wars','Toy Story','Jurassic Park'],correct:'Star Wars'},
{id:'falcon-droid',text:'Which of these Star Wars characters is a droid?',options:['R2-D2','Chewbacca','Han Solo'],correct:'R2-D2'}],
'ferrari-daytona':[
{id:'ferrari-country',text:'Which country is Ferrari originally from?',options:['Italy','Canada','Japan'],correct:'Italy'},
{id:'ferrari-wheels',text:'How many road wheels does a Ferrari Daytona SP3 have?',options:['Four','Two','Six'],correct:'Four'},
{id:'ferrari-type',text:'What type of vehicle is the Ferrari Daytona SP3?',options:['Sports car','Sailing boat','Helicopter'],correct:'Sports car'}],
'rivendell':[
{id:'rivendell-world',text:'In which fictional world is Rivendell located?',options:['Middle-earth','Narnia','Wonderland'],correct:'Middle-earth'},
{id:'rivendell-people',text:'Rivendell is famously home to which people?',options:['Elves','Pirates','Astronauts'],correct:'Elves'},
{id:'rivendell-author',text:'Who wrote The Lord of the Rings?',options:['J. R. R. Tolkien','Roald Dahl','Charles Dickens'],correct:'J. R. R. Tolkien'}]
};
let activeQuestion=null;const previousQuestions={};
function chooseQuestion(productId){const pool=questionPools[productId];const choices=pool.filter(q=>q.id!==previousQuestions[productId]);const question=choices[Math.floor(Math.random()*choices.length)];previousQuestions[productId]=question.id;const options=[...question.options];for(let i=options.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[options[i],options[j]]=[options[j],options[i]]}return {...question,options}}
function validEntryAnswer(entry){return !!questionPools[entry.id]?.some(q=>q.id===entry.questionId&&q.correct===entry.answer)}
let basket=[];let filter='All prizes';const money=n=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP'}).format(n/100);const app=document.querySelector('#app');const img=p=>p.image+'?format=png&width=1000';
function card(p){return `<article class="card"><a class="card-image" href="#/competition/${p.id}" aria-label="View ${p.name}"><span class="badge">${p.tag}</span><img src="${img(p)}" alt="LEGO ${p.name} building set"></a><div class="card-body"><div class="category">LEGO ${p.theme}</div><h3><a href="#/competition/${p.id}">${p.name}</a></h3><div class="meta"><span>Sample draw · 30 Sep 2026</span><span>${Math.round(p.sold/p.max*100)}% allocated</span></div><div class="progress"><span style="width:${p.sold/p.max*100}%"></span></div><div class="meta"><span>${p.sold} / ${p.max} sample entries</span><span>1 prize</span></div><div class="card-bottom"><div class="price">${money(p.price)}<small>per entry</small></div><a class="btn" href="#/competition/${p.id}">View competition <span>↗</span></a></div></div></article>`}
function catalogue(){return `<section id="competitions"><div class="section-head"><div><span class="eyebrow">MAKE ROOM ON YOUR SHELF</span><h2>Find your next great build.</h2><p>Explore our preview competition line-up.</p></div><div class="filters" aria-label="Competition view"><button class="chip active" aria-pressed="true">All prizes</button></div></div><div class="grid">${prizes.map(card).join('')}</div></section>`}
function how(){return `<section class="how"><span class="eyebrow">A FEW STEPS TO A BIG BUILD</span><h2>From wish list to what if.</h2><div class="steps"><div><span class="step-number">01 /</span><h3>Find your favourite</h3><p>Explore the sets and review the prize, entry price and competition details.</p></div><div><span class="step-number">02 /</span><h3>Choose your entries</h3><p>Answer the competition question and choose how many entries to add to your basket.</p></div><div><span class="step-number">03 /</span><h3>Look forward to draw day</h3><p>Live competitions will show their closing time and draw information before entries open.</p></div></div><div class="delivery-note"><span class="step-number">04 /</span><div><h3>We’ll post the prize</h3><p>When a winner is confirmed, the prize will be posted to their UK delivery address. Full delivery timings and requirements will be included in the final competition terms.</p></div></div></section>`}
function home(){app.innerHTML=`<div class="wrap"><section class="hero"><div class="hero-copy"><div class="eyebrow">FOR THE LOVE OF THE BUILD</div><h1>Small entry.<br><em>Epic possibility.</em></h1><p>Your dream set could be your next build. Discover competitions made for building fans.</p><a class="btn" href="#/competitions">Explore competitions <span>→</span></a></div><div class="hero-art"><span class="hero-tag">FEATURED SAMPLE PRIZE</span><img src="${img(prizes[0])}" alt="LEGO Millennium Falcon Ultimate Collector Series"><div class="feature-label">LEGO Star Wars™<strong>Millennium Falcon™ · ${money(prizes[0].price)} per entry</strong></div></div></section><div class="trust-strip"><span><b>✓</b> Clear entry limits</span><span><b>◇</b> Sets worth making space for</span><span><b>18+</b> UK residents</span></div>${catalogue()}${how()}</div>`}
function setFilter(f){filter=f;const el=document.querySelector('#competitions');el.outerHTML=catalogue()}
function detail(p){const question=chooseQuestion(p.id);activeQuestion=question;app.innerHTML=`<div class="wrap page"><div class="breadcrumb"><a href="#/competitions">Competitions</a> / ${p.name}</div><div class="detail"><div><div class="detail-photo"><img src="${img(p)}" alt="LEGO ${p.name}"></div><h2 style="font-size:32px;margin-top:30px">A build to get lost in.</h2><p>${p.description}</p><p>Set ${p.set} · ${p.pieces} pieces<br>Prize illustration from LEGO. Sample competition only.</p></div><div><span class="eyebrow">LEGO ${p.theme}</span><h1>${p.name}</h1><div class="price">${money(p.price)} <small>per sample entry · maximum 50 per person</small></div><div class="notice">Preview competition. Sample closing time: 30 September 2026, 8pm UK time. No live draw is scheduled.</div><div class="meta"><span>${p.sold} of ${p.max} sample entries allocated</span><span>1 prize</span></div><div class="progress"><span style="width:${p.sold/p.max*100}%"></span></div><form class="entry-box" id="entry-form"><fieldset class="question-options"><legend>First, answer the competition question</legend><p>${question.text}</p>${question.options.map(answer=>`<label class="answer-option"><input type="radio" name="answer" value="${answer}" required onchange="checkAnswer()"><span>${answer}</span></label>`).join("")}</fieldset><p id="answer-feedback" role="status" aria-live="polite">Choose the correct answer to unlock your tickets.</p><fieldset id="ticket-controls" disabled><label for="qty">Number of entries</label><div class="quantity"><button type="button" onclick="adjust(-1)" aria-label="Decrease entries">−</button><input id="qty" type="number" min="1" max="50" value="1" required oninput="updateTotal('${p.id}')"><button type="button" onclick="adjust(1)" aria-label="Increase entries">+</button></div><div class="total"><span>Entry total</span><span id="entry-total">${money(p.price)}</span></div><p id="entry-error" class="error" role="alert"></p><button class="btn full" type="submit">Continue to payment / log in <span>→</span></button></fieldset><p style="font-size:12px;margin-bottom:0">18+ · UK residents · <a href="#/terms" style="text-decoration:underline">Entry information</a></p></form></div></div></div>`;document.querySelector('#entry-form').onsubmit=e=>{e.preventDefault();const qty=Number(document.querySelector('#qty').value),answer=document.querySelector('input[name=answer]:checked')?.value;const old=basket.find(x=>x.id===p.id);if(answer!==question.correct){document.querySelector('#entry-error').textContent='Answer the question correctly before adding tickets.';return}if(!Number.isInteger(qty)||qty<1||qty+(old?.qty||0)>50){document.querySelector('#entry-error').textContent='Select an answer and keep your total to 1–50 entries for this competition.';return}if(old){old.qty+=qty;old.answer=answer;old.questionId=question.id}else basket.push({id:p.id,qty,answer,questionId:question.id});count();location.hash='/checkout'}}
function checkAnswer(){const answer=document.querySelector('input[name=answer]:checked')?.value;const correct=!!activeQuestion&&answer===activeQuestion.correct;document.querySelector('#ticket-controls').disabled=!correct;const feedback=document.querySelector('#answer-feedback');feedback.textContent=correct?'Correct! You can now choose your tickets.':'That’s not correct. Please try another answer.';feedback.className=correct?'answer-success':'error';document.querySelector('#entry-error').textContent=''}
function adjust(n){const el=document.querySelector('#qty');el.value=Math.min(50,Math.max(1,(Number(el.value)||1)+n));el.dispatchEvent(new Event('input'))}function updateTotal(id){document.querySelector('#entry-total').textContent=money(prizes.find(p=>p.id===id).price*(Number(document.querySelector('#qty').value)||0))}function count(){document.querySelector('#basket-count').textContent=basket.reduce((n,x)=>n+x.qty,0)}function total(){return basket.reduce((n,x)=>n+prizes.find(p=>p.id===x.id).price*x.qty,0)}
function basketPage(){app.innerHTML=`<div class="wrap page"><div class="breadcrumb"><a href="#/competitions">← Continue browsing</a></div><h1>Your basket.</h1>${basket.length?`<div class="basket-layout"><div>${basket.map(x=>{const p=prizes.find(p=>p.id===x.id);return `<div class="basket-row"><img src="${img(p)}" alt="${p.name}"><div style="flex:1"><h3><a href="#/competition/${p.id}">${p.name}</a></h3><div style="font-size:14px">${x.qty} ${x.qty===1?'entry':'entries'} × ${money(p.price)} · ${money(x.qty*p.price)}</div><div class="quantity"><button aria-label="Remove one entry for ${p.name}" onclick="changeQty('${p.id}',-1)">−</button><span style="padding:0 15px">${x.qty}</span><button aria-label="Add one entry for ${p.name}" onclick="changeQty('${p.id}',1)" ${x.qty===50?'disabled':''}>+</button></div><button class="remove" onclick="removeItem('${p.id}')">Remove</button></div></div>`}).join('')}<p style="font-size:14px">This preview basket lasts for this page session. Entries are not reserved.</p></div><aside class="summary"><h3>Order summary</h3><div class="total"><span>${basket.reduce((n,x)=>n+x.qty,0)} entries</span><span>${money(total())}</span></div><div class="total"><span>Total</span><span>${money(total())}</span></div><a class="btn full" href="#/checkout">Continue to checkout →</a><p style="font-size:12px">Preview only. No payment will be taken.</p></aside></div>`:`<div class="empty"><span class="eyebrow">YOUR NEXT BUILD IS WAITING</span><h2>A little room for possibility.</h2><p>Your basket is empty. Find a set you would love to build.</p><a class="btn" href="#/competitions">Explore competitions →</a></div>`}</div>`}
function removeItem(id){basket=basket.filter(x=>x.id!==id);count();basketPage()}function changeQty(id,n){const x=basket.find(x=>x.id===id);x.qty+=n;if(x.qty<1)basket=basket.filter(x=>x.id!==id);count();basketPage()}
function checkout(){if(basket.some(x=>!validEntryAnswer(x))){app.innerHTML='<div class="wrap page"><h1>Answer the question first.</h1><p>Each competition needs a correct answer before checkout.</p><a class="btn" href="#/competitions">Return to competitions</a></div>';return}if(!basket.length){basketPage();return}app.innerHTML=`<div class="wrap page"><div class="breadcrumb"><a href="#/basket">← Back to basket</a></div><h1>Account before payment.</h1><div class="basket-layout"><section class="checkout-panel"><div class="notice">You have answered the competition question correctly. The next live step will be to sign in or create an account before payment.</div><div class="checkout-auth"><a class="btn" href="/auth/signup">Create account</a><a class="btn outline" href="/auth/login">Sign in</a><span>Auth0 is connected for secure member login.</span></div><form id="checkout-form"><label class="form-field">UK postcode for delivery check<input name="postcode" autocomplete="postal-code" required pattern="[A-Za-z]{1,2}[0-9][A-Za-z0-9]? ?[0-9][A-Za-z]{2}" placeholder="SW1A 1AA"></label><label class="check"><input type="checkbox" required><span>I confirm I am aged 18 or over and a UK resident.</span></label><label class="check"><input type="checkbox" required><span>I understand this preview does not take payment or allocate entries yet.</span></label><button class="btn" type="submit">Review sample order →</button></form></section><aside class="summary"><h3>Your entries</h3>${basket.map(x=>`<p>${prizes.find(p=>p.id===x.id).name}<br>${x.qty} ${x.qty===1?'entry':'entries'}</p>`).join('')}<div class="total"><span>Total</span><span>${money(total())}</span></div><p style="font-size:14px">PayPal or another approved payment provider still needs to be connected before launch.</p></aside></div></div>`;document.querySelector('#checkout-form').onsubmit=e=>{e.preventDefault();app.innerHTML=`<div class="wrap page info"><span class="eyebrow">SAMPLE ORDER REVIEW</span><h1>Ready for payment setup.</h1><p>Your selection contains ${basket.reduce((n,x)=>n+x.qty,0)} entries with a sample total of ${money(total())}.</p><div class="notice">No order has been placed. Live account checks, payment and ticket allocation still need to be connected before launch.</div><a class="btn" href="#/basket">Return to basket</a></div>`;window.scrollTo(0,0)}}
const faqs=[['How many tickets are available for each prize?','Each prize competition is limited to 200 tickets in total. The preview shows sample allocations; no real tickets have been sold.'],['Is this website accepting entries?','Not yet. This preview demonstrates the browsing, selection and checkout journey. Every prize listing, entry price, entry allocation and closing date is illustrative.'],['Who will be able to enter?','The intended audience is UK residents aged 18 or over. Full eligibility and any territorial restrictions will be stated in the final competition terms.'],['How many entries can I choose?','This preview allows up to 50 entries per competition in your basket. Final limits will be published separately for every live competition.'],['How will winners be selected?','The draw method, draw timing and winner notification process must be confirmed and published before any competition opens.'],['Is a free entry route available?','The entry structure and any applicable free entry route are still to be finalised. Full entry instructions will be published before launch.'],['Is Win &amp; Build affiliated with LEGO?','No. Win &amp; Build is independent from the LEGO Group. Product names are used to identify the sets shown.']];
function info(kind){const content=kind==='faqs'?`<span class="eyebrow">THE USEFUL DETAILS</span><h1>A few good questions.</h1>${faqs.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}`:kind==='terms'?`<h1>Competition information.</h1><div class="notice">Pre-launch information. These are not final competition terms.</div><h2>About this preview</h2><p>All listings, prices, dates and entry counts are sample content. No competition is open, no entry can be purchased, and no prize or draw is promised by this preview.</p><h2>Before competitions open</h2><p>Each competition will need confirmed prize details, an entry cap, closing time, eligibility, entry methods, draw process, winner notification and delivery arrangements. The operator’s business identity and contact details, final terms and privacy policy must also be published.</p><h2>Independent brand</h2><p>Win &amp; Build is not sponsored, authorised or endorsed by the LEGO Group. LEGO and the product trademarks belong to their respective owners.</p>`:`<h1>Privacy in this preview.</h1><p>The basket is held in memory for the current page session. Refreshing the page clears it. Checkout details are not transmitted or stored by this application.</p><p>Product imagery loads from LEGO and fonts load from Google Fonts; those services receive the network requests needed to display those resources. The hosting service may process technical request data to serve the site.</p><h2>Before launch</h2><p>A full privacy notice identifying the operator, contact details, payment and service providers, retention periods and user rights is required before real customer details are collected.</p>`;app.innerHTML=`<div class="wrap page info">${content}</div>`}
function membersPage(){app.innerHTML=`<div class="wrap page"><div class="member-layout"><section><span class="eyebrow">YOUR WIN &amp; BUILD ACCOUNT</span><h1>A home for<br>your next big build.</h1><p>Create an account to return to your member area.</p><div class="member-benefits"><h3>One account. Your competitions.</h3><p>Sign in with your email and password. Account recovery will help you get back in if you forget your password.</p></div></section><section class="member-panel" aria-labelledby="member-title"><h2 id="member-title">Welcome to the club.</h2><p>Member registration is coming soon.</p><div class="notice">Accounts are not available yet. Please check back when registration opens.</div><button class="btn full" disabled>Create an account</button><button class="btn outline full" disabled style="margin-top:12px">Sign in</button><p style="font-size:14px;text-align:center">Already a member? Password recovery will be available here.</p></section></div></div>`;loadMemberAccount()}
function route(){const path=location.hash.slice(1)||'/';if(path==='/')home();else if(path==='/competitions')app.innerHTML=`<div class="wrap page">${catalogue()}${how()}</div>`;else if(path.startsWith('/competition/')){const p=prizes.find(p=>p.id===path.split('/')[2]);if(p)detail(p);else app.innerHTML='<div class="wrap page"><h1>Competition not found.</h1><a class="btn" href="#/competitions">Browse competitions</a></div>'}else if(path==='/members')membersPage();else if(path==='/basket')basketPage();else if(path==='/checkout')checkout();else if(path==='/how-it-works')app.innerHTML=`<div class="wrap page"><h1>Great builds start here.</h1>${how()}<div class="notice">This is a preview. Live competition and draw details will be published before launch.</div><a class="btn" href="#/competitions">Explore the sample prizes →</a></div>`;else if(['/faqs','/terms','/privacy'].includes(path))info(path.slice(1));else home();window.scrollTo(0,0);count()}window.addEventListener('hashchange',route);route();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'filter_competitions',description:'Filter the visible sample competition catalogue by theme. Does not purchase entries.',inputSchema:{type:'object',properties:{theme:{type:'string',enum:['All prizes','Star Wars™','Technic™','The Lord of the Rings™']}},required:['theme'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!['All prizes','Star Wars™','Technic™','The Lord of the Rings™'].includes(input.theme))throw new Error('Unknown competition theme');filter=input.theme;app.innerHTML=`<div class="wrap page">${catalogue()}${how()}</div>`;return {theme:filter,prizes:prizes.filter(p=>filter==='All prizes'||p.theme===filter).map(p=>({id:p.id,name:p.name}))}}})).catch(()=>{});}catch{}}
function termsPage(){app.innerHTML=`<div class="wrap page info"><span class="eyebrow">PLEASE READ BEFORE ENTERING</span><h1>Terms and conditions.</h1><div class="notice"><strong>Pre-launch draft.</strong> These working terms must be reviewed and completed by a UK legal adviser before any paid competition opens.</div><p>These terms apply to prize competitions hosted by Win &amp; Build (“we”, “us” or “the Promoter”). The Promoter’s legal name, company number, registered address and contact details will be added before launch.</p><h2>1. The competitions</h2><p>Each competition will display its prize, opening date, closing date, ticket price, maximum ticket allocation and competition question. Each prize competition is limited to <strong>200 tickets</strong>. The current advertised ticket price is £2.00 per ticket.</p><h2>2. How to enter</h2><p>You must create and use a member account, meet the eligibility requirements, answer the displayed multiple-choice question correctly, select your tickets and complete payment. A ticket is not allocated until payment is successfully confirmed.</p><p>Questions may be selected at random from that competition’s question set. You must answer the question shown to you.</p><h2>3. Free entry</h2><p>A free entry route will be provided where required by applicable law. The exact method, address, required information and deadlines will be published before paid entries open. Free entries will follow the same question, eligibility, ticket-limit and closing-time rules.</p><h2>4. Eligibility</h2><p>Unless stated otherwise, competitions are intended for UK residents aged 18 or over. Employees of the Promoter, people professionally connected with a competition and their immediate households may be excluded. We may request evidence of age, identity, address and eligibility.</p><h2>5. Closing and ticket availability</h2><p>Entries must be received before the published closing time. A competition may close when all 200 tickets are allocated. Entries received after closing or after allocation are not accepted.</p><h2>6. Winner and draw</h2><p>Eligible entries with a correct answer will be included in a random draw. The draw method, date, time and any live-stream details will be stated on the competition page. The Promoter will retain an auditable record of the draw.</p><h2>7. Contacting the winner</h2><p>We will contact the winner using the details on their member account. The winner may need to provide proof of identity and eligibility. If they cannot be contacted or do not claim within the stated period, an alternative winner may be selected under the published rules.</p><h2>8. Prize and delivery</h2><p>Once a winner is confirmed, the prize will be posted to the winner’s verified UK delivery address. Delivery timing, courier method and restrictions will be stated on the relevant competition page. Winners must keep their contact and delivery details current.</p><h2>9. Payments and refunds</h2><p>Payments will be processed by an approved third-party provider. We will not store full payment-card details. The final terms will explain failed payments, duplicate payments, refunds, cancellations and any prize substitution.</p><h2>10. Disqualification and misuse</h2><p>Entries or accounts may be voided or suspended where we reasonably suspect fraud, manipulation, automated entries, multiple accounts, payment abuse, interference with the website or a breach of these terms.</p><h2>11. Data and publicity</h2><p>Personal information will be used to administer competitions, process payments, deliver prizes and meet legal obligations in accordance with the Privacy Notice. Winner publicity and any opt-out process will be explained before launch.</p><h2>12. Independent brand</h2><p>Win &amp; Build is independent from the LEGO Group. LEGO and other product names are trademarks of their respective owners.</p><h2>13. Changes and governing law</h2><p>The final terms will state the governing law and courts that apply. Live competitions will not be changed in a way that unfairly disadvantages entrants.</p><div class="notice"><strong>Before launch:</strong> add the Promoter’s legal identity, completed free-entry route, final refund policy, delivery commitments and draw procedure, then obtain legal review.</div></div>`;window.scrollTo(0,0)}
window.addEventListener('hashchange',()=>{if(location.hash==='#/terms')termsPage()});if(location.hash==='#/terms')termsPage();
